// Original character meshes. Geometry is shared across the army and all NPCs.
function combine(parts){const attributes={position:[],normal:[],uv:[],color:[]};for(const {geometry,position=[0,0,0],scale=[1,1,1],rotation=[0,0,0]} of parts){const g=(geometry.index?geometry.toNonIndexed():geometry.clone()),matrix=new T.Matrix4().compose(new T.Vector3(...position),new T.Quaternion().setFromEuler(new T.Euler(...rotation)),new T.Vector3(...scale));g.applyMatrix4(matrix);for(let i=0;i<g.attributes.position.count;i++){for(const name of ['position','normal','uv','color']){const a=g.attributes[name],size=name==='uv'?2:3;for(let k=0;k<size;k++)attributes[name].push(a?a.array[i*a.itemSize+k]:name==='color'?1:0);}}g.dispose();}const out=new T.BufferGeometry();for(const [name,array] of Object.entries(attributes))out.setAttribute(name,new T.Float32BufferAttribute(array,name==='uv'?2:3));out.computeBoundingSphere();return out;}
function faceGeometry(heavy=false){const g=new T.SphereGeometry(1,24,18),p=g.attributes.position,colors=[];for(let i=0;i<p.count;i++){let x=p.getX(i),y=p.getY(i),z=p.getZ(i);const front=Math.max(0,z),jaw=y<-.15?1+(heavy?.22:.1)*Math.sin(Math.min(1,(-y-.15)/.85)*Math.PI):1;x*=jaw;z+=front*.1*Math.exp(-x*x*10-(y+.25)**2*10);y=Math.max(-.88,y);p.setXYZ(i,x,y,z);const cheek=Math.exp(-((Math.abs(x)-.57)**2*30+(y+.18)**2*35))*front;colors.push(1,1-cheek*.13,1-cheek*.16);}g.setAttribute('color',new T.Float32BufferAttribute(colors,3));g.computeVertexNormals();return g;}
function torso(){const v=[],uv=[],colors=[],indices=[],rings=[[-.5,.72,.7],[-.37,.77,.74],[-.14,.84,.78],[.15,1,.88],[.32,1.04,.82],[.45,.7,.6],[.5,.45,.45]],n=24;for(let row=0;row<rings.length;row++)for(let i=0;i<n;i++){const[y,w,d]=rings[row],a=i/n*Math.PI*2,fold=1+.018*Math.sin(a*7+y*5);v.push(Math.cos(a)*w*fold,y,Math.sin(a)*d*fold);uv.push(i/n,y+.5);const shade=.94+.06*(y+.5);colors.push(shade,shade,shade);if(row<rings.length-1){const a=row*n+i,b=(row+1)*n+i,c=(row+1)*n+(i+1)%n,d=row*n+(i+1)%n;indices.push(a,b,c,a,c,d);}}const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(v,3));g.setAttribute('uv',new T.Float32BufferAttribute(uv,2));g.setAttribute('color',new T.Float32BufferAttribute(colors,3));g.setIndex(indices);g.computeVertexNormals();return g;}
function capeGeometry(){const v=[],uv=[];for(let row=0;row<8;row++)for(let col=0;col<12;col++){const point=(r,c)=>{const t=r/8,x=(c/12-.5)*(.66-t*.12);return[x,-t*.55,-.065-Math.sin(t*Math.PI)*.1+Math.cos(c/12*Math.PI*8)*t*.025];};for(const[r,c]of[[row,col],[row+1,col],[row+1,col+1],[row,col],[row+1,col+1],[row,col+1]]){const p=point(r,c);v.push(...p);uv.push(c/12,r/8);}}const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(v,3));g.setAttribute('uv',new T.Float32BufferAttribute(uv,2));g.computeVertexNormals();return g;}
export function characterShapes(){const sphere=new T.SphereGeometry(1,16,12),capsule=new T.CapsuleGeometry(.5,1,4,10),hand=[{geometry:sphere,scale:[.65,.6,.32]}];for(let i=0;i<4;i++)hand.push({geometry:capsule,position:[-.45+i*.29,-.57+(i===0||i===3?.07:0),.02],scale:[.24,.37,.27]});hand.push({geometry:capsule,position:[.67,-.12,.12],scale:[.28,.4,.3],rotation:[0,.2,-.65]});const fist=[{geometry:sphere,scale:[.65,.65,.4]}];for(let i=0;i<4;i++)fist.push({geometry:capsule,position:[-.44+i*.29,-.26,.3],scale:[.27,.3,.32],rotation:[Math.PI/2,0,0]});fist.push({geometry:capsule,position:[.43,-.12,.53],scale:[.3,.45,.3],rotation:[0,0,.75]});const hair=new T.SphereGeometry(1,20,12,0,Math.PI*2,0,Math.PI*.63),p=hair.attributes.position;for(let i=0;i<p.count;i++){const x=p.getX(i),y=p.getY(i),z=p.getZ(i);p.setXYZ(i,x*(1+.025*Math.sin(z*14)),(z>0?Math.max(y,.4-Math.abs(x)*.14):y)+.025*Math.sin(x*10+z*7),z);}hair.computeVertexNormals();return{heroFace:faceGeometry(),heroJaw:faceGeometry(true),heroTorso:torso(),heroPalm:combine(hand),heroFist:combine(fist),heroBoot:combine([{geometry:sphere,position:[0,.05,-.22],scale:[.75,.85,.69]},{geometry:sphere,position:[0,-.35,.48],scale:[.8,.48,1.12]}]),heroCape:capeGeometry(),heroBelt:new T.CylinderGeometry(1,1,1,24),heroHair:hair,heroHood:new T.SphereGeometry(1,20,14,Math.PI,Math.PI,0,Math.PI*.8),heroBrow:new T.TubeGeometry(new T.QuadraticBezierCurve3(new T.Vector3(-.5,0,0),new T.Vector3(0,.18,.1),new T.Vector3(.5,.04,0)),8,.095,6,false)};}

export function replaceCharacter(g,type,M,part){const j=g.userData.joints,old=j.body,technology=g.userData.technology||0,species=g.userData.species||'human',enemy=g.userData.enemy,worker=type==='settler',archer=type==='archer',mystic=type==='psion',mounted=type==='cavalry',heavy=!worker&&!archer&&!mystic;
 g.remove(old);const body=new T.Group();g.add(body);body.position.y=mounted?.75:0;const team=enemy?M.red:species==='sylvan'?M.leaf:species==='astral'?M.glow:M.heroBlue,skin=species==='stonekin'?M.stone:species==='synthetic'?M.metal:M.skin,cloth=worker?M.linen:archer?M.heroGreen:technology>=23?M.iron:team,leather=M.leather,hair=archer?M.auburn:M.hair;
 const add=(parent,shape,material,x,y,z,a,b,c,rx=0,ry=0,rz=0)=>part(parent,shape,material,x,y,z,a,b,c,rx,ry,rz),orb=(parent,material,x,y,z,a,b,c)=>add(parent,'head',material,x,y,z,a,b,c);
 const chest=add(body,'heroTorso',cloth,0,.76,0,heavy?.285:archer?.205:.245,.49,.17);add(body,'cylinder',skin,0,1.025,0,.095,.17,.09);add(body,'heroTorso',M.darkwood,0,.5,0,.205,.13,.15);
 // Fitted vest / breastplate, raised seams, collar and substantial leather belt.
 if(worker){for(const side of[-1,1]){add(body,'heroTorso',team,side*.13,.79,.035,.12,.41,.15,0,0,side*.06);add(body,'limb',leather,side*.19,.78,.16,.025,.22,.025,0,0,side*-.12);}add(body,'heroTorso',leather,0,.58,.17,.16,.22,.025);}
 else{add(body,'heroTorso',technology>=12?M.iron:cloth,0,.8,.115,heavy?.24:.17,.34,.065);add(body,'limb',leather,.09,.77,.18,.035,.25,.025,0,0,-.32);}
 add(body,'heroBelt',leather,0,.545,0,.22,.065,.16);add(body,'box',M.gold,0,.545,.177,.085,.073,.026);add(body,'box',M.black,0,.545,.195,.048,.04,.01);
 const headPivot=new T.Group();headPivot.position.set(0,1.15,0);body.add(headPivot);const face=add(headPivot,heavy?'heroJaw':'heroFace',skin,0,0,0,heavy?.245:.222,.245,.205);const eyes=[];
 // Sockets, eyeballs, irises, eyebrows, nose, lips and ears are independent volumes.
 for(const side of[-1,1]){orb(headPivot,skin,side*.225,-.025,-.015,.046,.073,.038);orb(headPivot,M.skinShade,side*.229,-.024,.012,.02,.041,.015);orb(headPivot,skin,side*.085,.04,.17,.064,.045,.024);const eye=new T.Group();eye.position.set(side*.085,.045,.195);headPivot.add(eye);orb(eye,M.eyeWhite,0,0,0,.051,.034,.018);orb(eye,M.iris,0,-.002,.019,.022,.027,.01);orb(eye,M.black,0,-.002,.028,.011,.019,.006);orb(eye,M.eyeWhite,-.008,.009,.034,.005,.006,.003);eyes.push(eye);add(headPivot,'heroBrow',hair,side*.089,.112,.202,.13,.11,.15,0,0,side*(heavy?-.22:.08));}
 orb(headPivot,skin,0,-.025,.207,.035,.052,.038);for(const side of[-1,1])orb(headPivot,M.skinShade,side*.018,-.059,.233,.009,.006,.008);add(headPivot,'heroBrow',M.skinShade,0,-.126,.19,.14,.025,.08,0,0,Math.PI);orb(headPivot,skin,0,-.14,.178,.065,.008,.016);
 const hairCap=add(headPivot,'heroHair',hair,0,.025,-.018,.235,.257,.222);for(let i=0;i<3;i++)add(headPivot,'heroBrow',hair,-.08+i*.075,.255-i*.008,.055+i*.025,.2,.15,.22,0,.2,.35);if(worker){orb(headPivot,hair,0,-.178,.084,.125,.06,.09);for(const side of[-1,1])add(headPivot,'heroBrow',hair,side*.043,-.095,.209,.095,.09,.11,0,0,side*.15);}
 let cape=null;if(archer){cape=add(body,'heroCape',M.heroGreen,0,.94,-.1,1,1,1);for(const side of[-1,1])orb(headPivot,hair,side*.21,-.1,-.06,.07,.17,.09);orb(headPivot,hair,0,-.19,-.16,.105,.12,.12);add(headPivot,'heroHood',M.heroGreen,0,.025,-.053,.265,.295,.26);}
 else if(!worker&&technology>=12){add(headPivot,'heroHair',M.army,0,.034,-.018,.27,.28,.24);add(headPivot,'sandbag',M.army,0,.092,.07,.28,.05,.23);}
 else if(!worker&&!mystic){add(headPivot,'heroHair',M.iron,0,.035,-.025,.26,.27,.23);for(const side of[-1,1])add(headPivot,'limb',M.iron,side*.232,-.05,-.005,.05,.11,.1);add(headPivot,'limb',team,0,.25,-.075,.06,.1,.17,.2);}
 else if(worker){add(headPivot,'heroBrow',team,0,.205,.09,.35,.25,.25);}
 const limbs={};for(const side of[-1,1]){const label=side<0?'left':'right',arm=new T.Group();arm.position.set(side*(heavy?.315:archer?.255:.285),.94,0);body.add(arm);orb(arm,worker?cloth:skin,0,-.065,0,heavy?.135:.105,.13,.11);add(arm,'limb',worker?cloth:skin,0,-.125,0,heavy?.18:.14,.115,.16);if(!worker)orb(arm,archer?leather:technology>=12?M.army:M.iron,0,.015,-.005,heavy?.17:.125,.09,.14);const elbow=new T.Group();elbow.position.set(0,-.23,0);arm.add(elbow);add(elbow,'limb',skin,0,-.09,0,heavy?.17:.13,.105,.145);add(elbow,'cylinder',leather,0,-.17,0,.085,.065,.075);const hand=add(elbow,worker&&side<0?'heroPalm':'heroFist',skin,0,-.245,.015,.09,.105,.1,0,side<0?Math.PI:0);const leg=new T.Group();leg.position.set(side*.125,.5,0);body.add(leg);add(leg,'limb',archer?leather:M.heroTrousers,0,-.105,0,heavy?.18:.15,.125,.17);const knee=new T.Group();knee.position.set(0,-.24,0);leg.add(knee);add(knee,'limb',archer?skin:M.heroTrousers,0,-.075,0,.13,.09,.14);const boot=add(knee,'heroBoot',M.boots,0,-.135,.045,.115,.105,.14);add(knee,'cylinder',leather,0,-.04,0,.095,.07,.09);limbs[label+'Arm']=arm;limbs[label+'Elbow']=elbow;limbs[label+'Leg']=leg;limbs[label+'Knee']=knee;limbs[label+'Boot']=boot;limbs[label+'Hand']=hand;}
 const tool=new T.Group(),load=new T.Group();body.add(load);load.position.set(0,.73,-.22);orb(load,M.canvas,0,0,0,.22,.28,.17);add(load,'limb',leather,0,0,-.175,.025,.25,.02);load.visible=false;
 const right=limbs.rightElbow,left=limbs.leftElbow;right.add(tool);tool.position.set(0,-.245,.065);
 if(worker){add(tool,'cylinder',M.wood,0,.04,0,.025,.58,.025);add(tool,'chassis',M.iron,0,.285,.015,.25,.12,.065);add(tool,'cylinder',M.iron,0,.22,0,.035,.07,.035);}
 else if(archer){add(left,'ring',M.wood,0,-.19,.15,.16,.34,.16,0,Math.PI/2);add(left,'limb',M.cloth,0,-.19,.15,.012,.32,.012);add(body,'cylinder',leather,.16,.81,-.22,.08,.48,.08,.2);for(let i=0;i<3;i++)add(body,'limb',M.wood,.105+i*.04,1.075,-.24,.012,.16,.012);add(tool,'limb',M.wood,0,.01,.16,.012,.012,.44);}
 else if(type==='spearman'||mounted){add(tool,'cylinder',M.wood,0,.32,.03,.023,1.55,.023);add(tool,'cone',M.iron,0,1.15,.03,.075,.22,.045);add(left,'sandbag',M.iron,0,-.13,.14,.22,.3,.055);add(left,'sandbag',team,0,-.13,.19,.185,.255,.025);add(left,'ball',M.gold,0,-.13,.215,.05,.05,.02);}
 else if(mystic){add(tool,'cylinder',leather,0,.35,0,.028,1.2,.028);orb(tool,M.glow,0,1.03,0,.11,.13,.11);}
 else{add(tool,'chassis',M.iron,0,0,.19,.1,.13,.48);add(tool,'heroBoot',M.darkwood,0,-.075,.02,.05,.08,.075);add(tool,'cylinder',M.iron,0,.015,.5,.022,.3,.022,Math.PI/2);}
 if(mystic){add(body,'heroTorso',team,0,.48,0,.26,.38,.19);add(headPivot,'ring',M.gold,0,.02,-.11,.3,.3,.3,Math.PI/2);}
 Object.assign(j,limbs,{cape,body,headPivot,eyes,torso:chest,face,hairCap,tool:worker?tool:null,weapon:tool,load,hero:{worker,archer,heavy,mounted,mystic}});refineReferenceCharacter(g,type,M,part);g.userData.characterRevision=13;g.userData.sculptRevision=12;
}

export function characterEquipment(g,level,M,part){const j=g.userData.joints;if(!j?.hero||j.body.visible===false)return false;const {body,hero,headPivot}=j;for(let n=2;n<=level;n++){if(n===2)part(body,'sandbag',M.leather,.235,.59,.06,.08,.095,.06);if(n===3)for(const side of[-1,1])part(j[side<0?'leftArm':'rightArm'],'head',hero.worker||hero.archer?M.leather:M.iron,0,.025,0,.145,.085,.145);if(n===4)part(body,'heroBrow',M.gold,0,.93,.17,.16,.13,.12);if(n===5)part(body,'sandbag',M.leather,-.235,.64,.04,.08,.12,.07);if(n===6)part(body,'head',M.canvas,.22,.81,-.15,.12,.17,.1);if(n===7)for(const side of[-1,1])part(j[side<0?'leftElbow':'rightElbow'],'cylinder',M.iron,0,-.13,0,.09,.11,.08);if(n===8)part(headPivot,'ball',M.gold,.15,.14,.13,.033,.04,.02);if(n===9)part(body,'heroTorso',hero.worker?M.leather:M.iron,0,.74,.15,.2,.34,.035);if(n===10){part(body,'box',M.gold,0,.81,.195,.075,.11,.02);part(body,'heroBrow',M.gold,0,.95,.18,.25,.15,.1);}}return true;}

export function animateCharacter(j,u,time,moving,working,carrying){const h=j.hero,t=time*(h.heavy?6.3:7.2),stride=Math.sin(t),work=Math.sin(time*5.4),attack=!working&&!moving&&u.cooldown>.8?Math.min(1,(u.cooldown-.8)*2):0;j.body.position.y=(h.mounted?.75:-.035)+(moving?.022*(1-Math.cos(t*2)):Math.sin(time*1.7)*.006);j.body.rotation.set(moving?.07:working?.11:0,moving?stride*.035:working?work*.025:0,moving?stride*.025:Math.sin(time*1.3)*.009);
 j.leftLeg.rotation.x=moving?stride*.56:working?.07:0;j.rightLeg.rotation.x=moving?-stride*.56:working?-.09:0;j.leftKnee.rotation.x=moving?Math.max(0,-stride)*.95:working?.13:.05;j.rightKnee.rotation.x=moving?Math.max(0,stride)*.95:working?.18:.05;j.leftBoot.rotation.x=-j.leftLeg.rotation.x*.35-j.leftKnee.rotation.x*.35;j.rightBoot.rotation.x=-j.rightLeg.rotation.x*.35-j.rightKnee.rotation.x*.35;
 j.leftArm.rotation.set(moving?-stride*.42:working?-.35:carrying?-.35:-.06,0,-.08);j.rightArm.rotation.set(moving?stride*.42:working?-.75+work*.65:-.1-attack*.9,0,.08);j.leftElbow.rotation.x=working?-.4:moving?-.15-Math.max(0,stride)*.35:-.14;j.rightElbow.rotation.x=working?-.55+work*.45:-.14-attack*.4;if(h.archer&&attack){j.leftArm.rotation.x=-1.25;j.rightArm.rotation.x=-1;j.rightElbow.rotation.x=-1.1;}j.headPivot.rotation.set(working?.09:Math.sin(time*.8)*.025,Math.sin(time*.6)*.035,-j.body.rotation.z*.5);const blink=(time+(h.heavy?.7:0))%4.4;j.eyes.forEach(e=>e.scale.y=blink<.12?.12:1);if(j.cape)j.cape.rotation.x=moving?.06+Math.sin(time*5)*.035:.01;j.load.visible=carrying;if(j.tool)j.tool.visible=!working||!['food','water'].includes(u.gatherResource);}
